CREATE TABLE IF NOT EXISTS family_supervision_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid UNIQUE NOT NULL REFERENCES families(id) ON DELETE CASCADE,frequency_days int NOT NULL DEFAULT 7 CHECK(frequency_days BETWEEN 1 AND 365),next_due_at date NOT NULL DEFAULT(current_date+7),last_approved_report_at timestamptz,active boolean NOT NULL DEFAULT true,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO family_supervision_plans(family_id,next_due_at) SELECT family_id,current_date+7 FROM family_supervisor_assignments WHERE ends_at IS NULL ON CONFLICT(family_id) DO NOTHING;
CREATE TABLE IF NOT EXISTS supervision_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE,supervisor_id uuid NOT NULL REFERENCES supervisors(id),liaison_id uuid NOT NULL REFERENCES users(id),week_start date NOT NULL,contact_at timestamptz NOT NULL,contact_method text NOT NULL CHECK(contact_method IN ('phone','message','in_person_with_supervisor')),checklist jsonb NOT NULL DEFAULT '{}',priority text NOT NULL CHECK(priority IN ('low','normal','high','urgent')),summary text NOT NULL,proposed_actions text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','revision_requested')),submitted_at timestamptz,reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,review_note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(family_id,week_start));
CREATE INDEX IF NOT EXISTS supervision_reports_review_idx ON supervision_reports(status,submitted_at DESC);
CREATE INDEX IF NOT EXISTS supervision_reports_family_idx ON supervision_reports(family_id,week_start DESC);
CREATE INDEX IF NOT EXISTS supervision_plans_due_idx ON family_supervision_plans(next_due_at) WHERE active;
